from pathlib import Path
svg='<svg xmlns="http://www.w3.org/2000/svg" width="680" height="120" viewBox="0 0 680 120" role="img">\n<title>Capsule slice/cylinder</title><desc>two more capsule types</desc>\n<rect width="680" height="120" rx="16" fill="#0f172a"/>\n<text x="20" y="24" fill="#e2e8f0" font-family="monospace" font-size="12">CAPSULE — slice / cylinder · 3 types of capsule-render</text>\n<g transform="translate(20,36)">\n  <path d="M0 0 L 320 0 L 300 44 L 0 44 Z" fill="url(#g1)"/><text x="150" y="26" text-anchor="middle" fill="white" font-family="monospace" font-size="11">type=slice</text>\n  <g transform="translate(340,0)"><rect width="320" height="44" rx="22" fill="url(#g2)"/><text x="160" y="26" text-anchor="middle" fill="white" font-family="monospace" font-size="11">type=cylinder</text></g>\n  <defs><linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#7c3aed"/><stop offset="1" stop-color="#ec4899"/></linearGradient><linearGradient id="g2" x1="0" x2="1"><stop offset="0" stop-color="#06b6d4"/><stop offset="1" stop-color="#22c55e"/></linearGradient></defs>\n</g>\n<text x="20" y="104" fill="#64748b" font-family="monospace" font-size="9">capsule-render.vercel.app/api?type=slice|cylinder|waving|transparent|rect|soft|shark</text>\n</svg>\n'
Path(__file__).resolve().parents[2].joinpath('assets','capsule-slice.svg').write_text(svg, encoding='utf-8')
print('Wrote assets/capsule-slice.svg')
